type metricOracledbAsmDiskgroupFreeMb struct {
	data     pmetric.Metric // data buffer for generated metric.
	config   MetricConfig   // metric config provided by user.
	capacity int            // max observed number of data points added to the metric.
}

// init fills oracledb.asm.diskgroup.free_mb metric with initial data.
func (m *metricOracledbAsmDiskgroupFreeMb) init() {
	m.data.SetName("oracledb.asm.diskgroup.free_mb")
	m.data.SetDescription("Available free space in the ASM disk group in MB")
	m.data.SetUnit("MB")
	m.data.SetEmptyGauge()
	m.data.Gauge().DataPoints().EnsureCapacity(m.capacity)
}

func (m *metricOracledbAsmDiskgroupFreeMb) recordDataPoint(start pcommon.Timestamp, ts pcommon.Timestamp, val float64, diskgroupNameAttributeValue string) {
	if !m.config.Enabled {
		return
	}
	dp := m.data.Gauge().DataPoints().AppendEmpty()
	dp.SetStartTimestamp(start)
	dp.SetTimestamp(ts)
	dp.SetDoubleValue(val)
	dp.Attributes().PutStr("diskgroup.name", diskgroupNameAttributeValue)
}

// updateCapacity saves max length of data point slices that will be used for the slice capacity.
func (m *metricOracledbAsmDiskgroupFreeMb) updateCapacity() {
	if m.data.Gauge().DataPoints().Len() > m.capacity {
		m.capacity = m.data.Gauge().DataPoints().Len()
	}
}

// emit appends recorded metric data to a metrics slice and prepares it for recording another set of data points.
func (m *metricOracledbAsmDiskgroupFreeMb) emit(metrics pmetric.MetricSlice) {
	if m.config.Enabled && m.data.Gauge().DataPoints().Len() > 0 {
		m.updateCapacity()
		m.data.MoveTo(metrics.AppendEmpty())
		m.init()
	}
}

func newMetricOracledbAsmDiskgroupFreeMb(cfg MetricConfig) metricOracledbAsmDiskgroupFreeMb {
	m := metricOracledbAsmDiskgroupFreeMb{config: cfg}

	if cfg.Enabled {
		m.data = pmetric.NewMetric()
		m.init()
	}
	return m
}

